$<rv6_before><style data-rv6-stella-tabs>
.rv6-drawer{
  --rv6-pink:#ff70bd;--rv6-hot:#ff3e9d;--rv6-violet:#9d7bff;
  --rv6-text:#f4eff7;--rv6-muted:#aaa2b8;--rv6-deep:#0b0913;--rv6-panel:#151120;
  box-sizing:border-box;width:100%;margin:0 auto;text-align:center;
  font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif
}
.rv6-drawer,.rv6-drawer *{box-sizing:border-box}
.rv6-launch{
  position:relative;isolation:isolate;display:inline-flex;align-items:center;justify-content:center;gap:9px;
  min-height:42px;margin:16px auto 0;padding:10px 23px;overflow:hidden;cursor:pointer;list-style:none;
  border:1px solid color-mix(in srgb,var(--lumiverse-primary,#ff70bd) 46%,var(--lumiverse-border,rgba(255,112,189,.3)) 54%);
  border-radius:13px;
  background:radial-gradient(circle at 20% 20%,color-mix(in srgb,var(--lumiverse-primary-text,#ffd9ed) 9%,transparent),transparent 32%),
    linear-gradient(180deg,color-mix(in srgb,var(--lumiverse-bg-elevated,#241420) 78%,var(--lumiverse-primary,#ff70bd) 22%),
    color-mix(in srgb,var(--lumiverse-bg-deep,#0b0710) 91%,var(--lumiverse-primary,#ff70bd) 9%));
  color:var(--lumiverse-primary-text,#ffd9ed);
  font:800 10px/1 var(--lumiverse-font-mono,"Courier New",monospace);letter-spacing:.19em;text-transform:uppercase;
  box-shadow:var(--lumiverse-shadow-lg,0 12px 32px rgba(0,0,0,.34)),
    0 0 20px color-mix(in srgb,var(--lumiverse-primary,#ff70bd) 18%,transparent),
    inset 0 1px color-mix(in srgb,var(--lumiverse-text,#fff) 9%,transparent);
  -webkit-tap-highlight-color:transparent
}
.rv6-launch::-webkit-details-marker{display:none}.rv6-launch::marker{content:""}
.rv6-label{position:relative;z-index:2;display:inline-flex;align-items:center;gap:9px}
.rv6-sparks{position:absolute;inset:0;z-index:1;overflow:hidden;pointer-events:none}
.rv6-sparks i{
  --x:50%;--y:50%;--dx:0px;--dy:-24px;--size:3px;--dur:8s;--delay:0s;
  position:absolute;left:var(--x);top:var(--y);width:var(--size);height:var(--size);border-radius:999px;
  background:radial-gradient(circle,#fff 0 22%,#ffb3d9 34%,rgba(255,112,189,.3) 64%,transparent 72%);
  box-shadow:0 0 5px rgba(255,255,255,.68),0 0 11px rgba(255,62,157,.3);
  opacity:0;animation:rv6spark var(--dur) ease-in-out var(--delay) infinite;will-change:transform,opacity
}
.rv6-sparks i:nth-child(1){--x:7%;--y:76%;--dx:8px;--dy:-34px;--size:2px;--dur:8.2s;--delay:-1.2s}
.rv6-sparks i:nth-child(2){--x:18%;--y:23%;--dx:-5px;--dy:-26px;--size:3px;--dur:9.6s;--delay:-5s}
.rv6-sparks i:nth-child(3){--x:31%;--y:83%;--dx:4px;--dy:-42px;--size:2px;--dur:10.8s;--delay:-3.8s}
.rv6-sparks i:nth-child(4){--x:48%;--y:17%;--dx:7px;--dy:-28px;--size:2px;--dur:7.9s;--delay:-6.1s}
.rv6-sparks i:nth-child(5){--x:64%;--y:79%;--dx:-6px;--dy:-37px;--size:3px;--dur:9.2s;--delay:-2.6s}
.rv6-sparks i:nth-child(6){--x:80%;--y:29%;--dx:5px;--dy:-31px;--size:2px;--dur:11.2s;--delay:-7.4s}
.rv6-sparks i:nth-child(7){--x:92%;--y:70%;--dx:-8px;--dy:-30px;--size:3px;--dur:8.8s;--delay:-4.7s}
.rv6-sparks i:nth-child(8){--x:72%;--y:11%;--dx:4px;--dy:-21px;--size:2px;--dur:10.4s;--delay:-1.8s}
@keyframes rv6spark{
  0%{opacity:0;transform:translate3d(0,10px,0) scale(.45)}
  18%{opacity:.72}55%{opacity:.96}
  100%{opacity:0;transform:translate3d(var(--dx),var(--dy),0) scale(1.18)}
}
.rv6-card{
  position:relative;isolation:isolate;width:min(100%,640px);margin:16px auto;overflow:hidden;
  border:1px solid rgba(255,112,189,.56);border-radius:24px;
  background:linear-gradient(155deg,rgba(24,19,35,.98),rgba(10,9,18,.99) 62%);
  color:var(--rv6-text);text-align:left;
  box-shadow:0 22px 70px rgba(0,0,0,.36),0 0 0 1px rgba(255,255,255,.035) inset,0 0 36px rgba(255,62,157,.08);
  content-visibility:auto;contain-intrinsic-size:420px
}
.rv6-tabform{margin:0}
.rv6-tabbar{
  display:grid;grid-template-columns:1fr 1fr;min-height:66px;padding:5px;
  border-bottom:1px solid rgba(255,112,189,.2);background:rgba(5,4,12,.48)
}
.rv6-tab{
  position:relative;display:flex;align-items:center;justify-content:center;gap:9px;
  padding:14px 18px;border-radius:14px;color:var(--rv6-muted);cursor:pointer;
  font-size:12px;font-weight:800;letter-spacing:.07em;text-transform:uppercase;user-select:none
}
.rv6-tab input{position:absolute;opacity:0;pointer-events:none;width:1px;height:1px}
.rv6-tab:has(input:checked){
  border:1px solid rgba(255,112,189,.25);
  background:linear-gradient(135deg,rgba(255,112,189,.15),rgba(157,123,255,.1));
  color:var(--rv6-pink);
  text-shadow:0 0 18px rgba(255,112,189,.3);
  box-shadow:0 8px 24px rgba(255,62,157,.08),inset 0 1px rgba(255,255,255,.045)
}
.rv6-panes{padding:20px}.rv6-pane-b{display:none}
.rv6-tabform:has(.rv6-tab-b input:checked) .rv6-pane-a{display:none}
.rv6-tabform:has(.rv6-tab-b input:checked) .rv6-pane-b{display:block}
.rv6-media{
  position:relative;overflow:hidden;border:1px solid rgba(255,112,189,.18);border-radius:17px;
  background:linear-gradient(145deg,rgba(255,255,255,.035),rgba(255,255,255,.012));
  box-shadow:inset 0 1px rgba(255,255,255,.035);contain:paint
}
.rv6-media:empty{display:none}.rv6-media image_request,.rv6-media scene_brief{display:none!important}
.rv6-media img{display:block!important;width:100%!important;height:100%!important;object-fit:cover!important;border-radius:inherit!important}
.rv6-wide{aspect-ratio:16/9;max-height:300px}.rv6-wide img{min-height:180px!important;max-height:300px!important}
.rv6-portrait{aspect-ratio:1/1}
.rv6-kicker{margin:0 0 5px;color:var(--rv6-pink);font-size:9px;font-weight:850;letter-spacing:.13em;text-transform:uppercase}
.rv6-title{margin:0;color:var(--rv6-text);font-size:19px;font-weight:850;letter-spacing:-.02em}
.rv6-sub{margin:5px 0 0;color:var(--rv6-muted);font-size:11px;line-height:1.45}
.rv6-profile{display:grid;grid-template-columns:150px minmax(0,1fr);gap:15px;align-items:start}
.rv6-profile-head{padding:2px 0 11px;border-bottom:1px solid rgba(255,112,189,.14)}
.rv6-file{
  margin-top:11px;padding:14px 15px;border:1px solid rgba(255,255,255,.055);border-radius:16px;
  background:rgba(4,3,10,.28);color:var(--rv6-text);font-size:11.5px;line-height:1.66;
  white-space:pre-line;overflow-wrap:anywhere
}
.rv6-grid3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.rv6-thread{overflow:hidden;border:1px solid rgba(255,255,255,.065);border-radius:16px;background:rgba(4,3,10,.25);contain:content}
.rv6-thread .rv6-media{border:0;border-radius:0;border-bottom:1px solid rgba(255,112,189,.14);aspect-ratio:4/3}
.rv6-thread p{margin:0;padding:12px;color:var(--rv6-text);font-size:11.5px;line-height:1.5}
.rv6-chipbar{display:flex;flex-wrap:wrap;gap:8px}
.rv6-chip{
  padding:7px 10px;border:1px solid rgba(255,112,189,.2);border-radius:999px;background:rgba(255,112,189,.055);
  color:var(--rv6-muted);font-size:9px;font-weight:800;letter-spacing:.05em
}
.rv6-chip strong{color:var(--rv6-pink)}
.rv6-info{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:11px}
.rv6-box{padding:12px 13px;border:1px solid rgba(255,255,255,.06);border-radius:14px;background:rgba(4,3,10,.25)}
.rv6-box small{display:block;margin-bottom:6px;color:var(--rv6-muted);font-size:8px;font-weight:850;letter-spacing:.12em;text-transform:uppercase}
.rv6-box p{margin:0;color:var(--rv6-text);font-size:11.5px;line-height:1.5}
.rv6-context{margin-top:9px}
.rv6-prose{color:var(--rv6-text);font-family:Georgia,"Times New Roman",serif;font-size:13.5px;line-height:1.72;white-space:pre-line}
.rv6-foot{
  margin-top:14px;padding:9px 11px;border:1px solid rgba(255,112,189,.16);border-radius:12px;
  background:rgba(255,112,189,.045);color:var(--rv6-muted);font-size:8px;font-weight:850;
  letter-spacing:.1em;text-align:center;text-transform:uppercase
}
.rv6-fork{
  display:flex;align-items:center;justify-content:center;gap:8px;width:100%;margin-top:14px;padding:11px 14px;
  border:1px solid rgba(255,112,189,.38);border-radius:13px;
  background:linear-gradient(135deg,rgba(255,112,189,.14),rgba(157,123,255,.08));
  color:var(--rv6-pink);font:850 9px/1 var(--lumiverse-font-mono,"Courier New",monospace);
  letter-spacing:.11em;text-transform:uppercase;cursor:pointer
}
.rv6-fork[data-lumiverse-regex-action-used="true"]{opacity:.55;cursor:not-allowed}
@media(max-width:600px){
  .rv6-card{contain-intrinsic-size:360px;box-shadow:0 14px 34px rgba(0,0,0,.30),0 0 0 1px rgba(255,255,255,.03) inset}
  .rv6-panes{padding:14px}.rv6-profile{grid-template-columns:102px minmax(0,1fr)}
  .rv6-grid3{display:grid;grid-auto-flow:column;grid-auto-columns:minmax(245px,78vw);grid-template-columns:none;gap:10px;overflow-x:auto;overflow-y:hidden;padding:0 2px 8px;scroll-snap-type:x mandatory;-webkit-overflow-scrolling:touch;overscroll-behavior-inline:contain;scrollbar-width:thin}.rv6-thread{scroll-snap-align:start;min-width:0}.rv6-info{grid-template-columns:1fr}
  .rv6-tabbar{min-height:56px}.rv6-tab{padding:11px 8px;font-size:10px}
  .rv6-wide{max-height:220px}.rv6-wide img{min-height:150px!important;max-height:220px!important}
  .rv6-sparks i:nth-child(n+5){display:none}
  .rv6-sparks i{box-shadow:0 0 4px rgba(255,255,255,.55),0 0 8px rgba(255,62,157,.22)}
}
@media(max-width:430px){.rv6-profile{grid-template-columns:1fr}.rv6-portrait{width:min(52%,160px)}}
@media(prefers-reduced-motion:reduce){.rv6-sparks i{animation:none!important;opacity:.4}}
</style>$<rv6_first>
